use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap = 0
    let mut first = true
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut nk: Vec<int> = [k]
            let mut nv: Vec<int> = [v]
            let n: int = ks.len() as int
            let mut i = 0
            while i < n {
                if ks[i as usize] != k {
                    nk.push(ks[i as usize])
                    nv.push(vs[i as usize])
                }
                i += 1
            }
            if nk.len() as int > cap {
                println("evict ${nk[nk.len() - 1]}")
                nk.pop()
                nv.pop()
            }
            ks = nk
            vs = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let n: int = ks.len() as int
            let mut idx: int = -1
            let mut i = 0
            while i < n {
                if ks[i as usize] == k { idx = i }
                i += 1
            }
            if idx < 0 {
                println("-1")
            } else {
                let v = vs[idx as usize]
                let mut nk: Vec<int> = [k]
                let mut nv: Vec<int> = [v]
                let mut j = 0
                while j < n {
                    if j != idx {
                        nk.push(ks[j as usize])
                        nv.push(vs[j as usize])
                    }
                    j += 1
                }
                ks = nk
                vs = nv
                println("${v}")
            }
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = 0
                while i < ks.len() as int {
                    if i > 0 { out = out + " " }
                    out = out + "${ks[i as usize]}"
                    i += 1
                }
                println(out)
            }
        }
    }
}

